"""Public visitor board with nickname posting and owner-managed replies."""
from html import escape
ROUTES=['/questions/']
TRANSLATIONS={}
def t(ko,en):
    TRANSLATIONS[ko]=en
    return escape(ko)
LABEL=t('질문과 답변','Questions & answers')
TITLE=t('궁금한 장면, 만드는 사람에게.','Ask the person behind the frame.')
DESC=t('드래곤시네마 작품과 AI 영상 제작에 관한 공개 게시판. 닉네임으로 글을 남기고 제작자와 이야기를 나누세요.','A public board for DRA9ON CINEMA stories and AI filmmaking. Post with a nickname and hear from the creator.')
TRANSLATIONS[TITLE+' | DRA9ON CINEMA']='Ask the person behind the frame. | DRA9ON CINEMA'

def build_questions(out,origin,head,header,footer):
    topics=''.join(f'<option value="{key}">{t(ko,en)}</option>' for key,ko,en in [('story','작품·세계관','Stories & worlds'),('making','AI 제작·튜토리얼','AI filmmaking & tutorials'),('other','감상·기타','Thoughts & other')])
    body=f'''<body class="watch-page">{header()}<main class="tutorial-main questions-main" id="main"><a class="note-back" href="/">← {t('사이트로 돌아가기','Back to the site')}</a><header class="tutorial-heading"><p class="section-eyebrow">DRA9ON CINEMA / QUESTIONS &amp; ANSWERS</p><h1>{TITLE}</h1><p class="tutorial-intro">{DESC}</p><p>{t('회원가입이나 로그인 없이 닉네임으로 참여하세요. 남긴 글과 제작자의 답변은 누구나 볼 수 있습니다.','Join with a nickname, without registration or a sign-in screen. Everyone can read your posts and the creator’s replies.')}</p><a href="#ask" class="button button-white">{t('글 남기기','Write a post')} ↓</a></header><section class="question-answers" aria-labelledby="posts-heading"><p class="section-eyebrow">PUBLIC BOARD</p><h2 id="posts-heading">{t('최근 질문과 답변','Recent questions and answers')}</h2><div class="tutorial-actions"><label for="board-filter">{t('불러온 글의 분야','Filter loaded posts')}</label><select id="board-filter"><option value="all">{t('전체','All')}</option>{topics}</select><button id="board-refresh" class="button button-glass" type="button">{t('새로고침','Refresh')}</button></div><p id="board-status" role="status" aria-live="polite">{t('게시판을 불러오는 중…','Loading the board…')}</p><div id="board-posts"></div><button id="board-more" class="button button-glass" type="button" hidden>{t('이전 글 더 보기','More previous posts')}</button><noscript>{t('게시판을 읽고 쓰려면 JavaScript를 켜주세요.','Enable JavaScript to read and write board posts.')}</noscript></section><section id="ask" class="qna-panel"><p class="section-eyebrow">YOUR VOICE</p><h2>{t('닉네임으로 글 남기기','Post with a nickname')}</h2><p class="tutorial-notice">{t('이곳은 공개 게시판입니다. 이름·이메일·전화번호·비밀번호 등 개인정보는 쓰지 마세요. 비공개 문의는 페이지 아래 채널 문의 이메일을 이용해 주세요.','This is a public board. Do not include names, email addresses, phone numbers or passwords. For private enquiries, use the channel email in the footer.')}</p><form id="board-form"><label for="board-nickname">{t('닉네임','Nickname')}</label><input id="board-nickname" required minlength="2" maxlength="24" autocomplete="off"><label for="board-topic">{t('분야','Topic')}</label><select id="board-topic">{topics}</select><label for="board-title">{t('제목','Title')}</label><input id="board-title" required minlength="2" maxlength="120"><label for="board-body">{t('내용','Post')}</label><textarea id="board-body" required minlength="10" maxlength="3000" rows="7" placeholder="{t('작품 감상이나 궁금한 점을 적어주세요. 제작 질문은 사용 도구·원하는 결과·문제·전체 프롬프트를 함께 적으면 답변에 도움이 됩니다.','Share your thoughts or questions. For filmmaking help, include your tool, intended result, issue and the full prompt you tried.')}"></textarea><div class="qna-trap" aria-hidden="true"><label for="board-website">Website</label><input id="board-website" tabindex="-1" autocomplete="off"></div><label class="qna-check"><input type="checkbox" id="board-consent" required> {t('글·닉네임의 공개 게시와 글쓰기용 브라우저 식별정보 처리에 동의합니다.','I agree to public posting of my text and nickname, and processing of a browser identity for posting.')} <a href="/privacy/">{t('개인정보처리방침','Privacy policy')}</a></label><button type="submit" id="board-submit" class="button button-white">{t('공개 게시하기','Publish post')}</button></form><p id="board-write-status" role="status" aria-live="polite"></p><p class="tutorial-notice">{t('같은 브라우저에서는 10분에 한 번 글을 올릴 수 있습니다. 답변은 제작자가 직접 작성하며 시간이 걸릴 수 있습니다. 광고·도배·욕설·개인정보가 포함된 글은 운영자가 숨길 수 있습니다. 수정·삭제 요청은 아래 채널 문의로 보내주세요.','One post per 10 minutes from the same browser. Replies are written by the creator and may take time. The creator may hide spam, advertising, abusive posts or personal information. Use the channel email below for edit or deletion requests.')}</p></section><section class="qna-panel"><h2>{t('제작자 관리','Creator management')}</h2><p>{t('방문자는 로그인할 필요가 없습니다. 제작자만 아래에서 로그인해 답변과 게시글을 관리합니다.','Visitors do not need to sign in. Only the creator uses the sign-in below to manage posts and replies.')}</p><div class="tutorial-actions"><button id="board-owner-login" class="button button-glass" type="button">{t('제작자 Google 로그인','Creator Google sign-in')}</button><button id="board-owner-redirect" class="button button-glass" type="button">{t("현재 창에서 로그인", "Sign in in this tab")}</button><button id="board-owner-logout" class="button button-glass" type="button" hidden>{t('로그아웃','Sign out')}</button></div><p id="board-owner-status" role="status"></p><div id="board-owner-panel" hidden><h3>{t('숨긴 글 보관함','Hidden posts archive')}</h3><p>{t('숨긴 글은 공개 게시판에서 내려가며 이 보관함에서 복원할 수 있습니다.','Hidden posts leave the public board and can be restored from this archive.')}</p><button id="board-archive-refresh" class="button button-glass" type="button">{t('보관함 불러오기','Load archive')}</button><div id="board-archive"></div><button id="board-archive-more" class="button button-glass" type="button" hidden>{t('보관한 글 더 보기','More archived posts')}</button></div></section></main>{footer()}<script src="/engagement-config.js"></script><script type="module" src="/community.js?v=20261011-board2"></script></body></html>'''
    schema={'@context':'https://schema.org','@type':'WebPage','name':TITLE,'description':DESC,'url':origin+ROUTES[0]}
    page=out/'questions';page.mkdir(parents=True,exist_ok=True)
    (page/'index.html').write_text(head(TITLE+' | DRA9ON CINEMA',DESC,ROUTES[0],schema).replace('property="og:type" content="video.episode"','property="og:type" content="website"')+body,encoding='utf-8')
